namespace Open.Database.Extensions;

/// <summary>
/// Represents the base class of the expressive commands that execute on a
/// database with the asynchronous ADO.NET APIs, for use with
/// <see cref="DbConnection"/> and <see cref="DbCommand"/> types.
/// </summary>
/// <typeparam name="TConnection">The type of the connection to be used.</typeparam>
/// <typeparam name="TCommand">The type of the commands generated by the connection.</typeparam>
/// <typeparam name="TReader">The type of reader created by the command.</typeparam>
/// <typeparam name="TDbType">The DB type enum to use for parameters.</typeparam>
/// <typeparam name="TThis">The type of the derived class, so that the chaining methods return it.</typeparam>
public abstract partial class ExpressiveDbCommandBase<TConnection, TCommand, TReader, TDbType, TThis>
	: ExpressiveCommandBase<TConnection, TCommand, TReader, TDbType, TThis>, IExecuteReaderAsync<TReader>
	where TConnection : DbConnection
	where TCommand : DbCommand
	where TReader : DbDataReader
	where TDbType : struct
	where TThis : ExpressiveDbCommandBase<TConnection, TCommand, TReader, TDbType, TThis>
{
	const string LaterSets = "Map also reads the later result sets, so a failure in one is thrown; to read only the first, as this method does, call .SingleResult() before Map (cmd.SingleResult().Map(...); .Map(...).SingleResult() still works).";
	const string ToListAsyncObsolete = "Use .Map(selector).ToListAsync(cancellationToken) instead. " + LaterSets + " Map has no CommandBehavior argument: if you passed one, use var list = new List<T>(); await cmd.IterateReaderAsync(r => list.Add(selector(r)), behavior). Removed in 12.";

	/// <summary>
	/// Initializes a new instance that takes its connections from a
	/// connection pool.
	/// </summary>
	/// <include file="Commands.docs.xml" path="docs/members[@name='ctorPool']/*" />
	/// <include file="Commands.docs.xml" path="docs/members[@name='ctorCommon']/*" />
	protected ExpressiveDbCommandBase(
		IDbConnectionPool<TConnection> connectionPool,
		CommandType type,
		string command,
		IEnumerable<Param>? @params = null)
		: base(connectionPool, type, command, @params)
	{
	}

	/// <summary>
	/// Initializes a new instance that creates a new connection from a
	/// connection factory for each execution.
	/// </summary>
	/// <include file="Commands.docs.xml" path="docs/members[@name='ctorFactory']/*" />
	/// <include file="Commands.docs.xml" path="docs/members[@name='ctorCommon']/*" />
	protected ExpressiveDbCommandBase(
		IDbConnectionFactory<TConnection> connFactory,
		CommandType type,
		string command,
		IEnumerable<Param>? @params = null)
		: base(connFactory, type, command, @params)
	{
	}

	/// <summary>
	/// Initializes a new instance that invokes a function to create a new
	/// connection for each execution.
	/// </summary>
	/// <include file="Commands.docs.xml" path="docs/members[@name='ctorFunc']/*" />
	/// <include file="Commands.docs.xml" path="docs/members[@name='ctorCommon']/*" />
	protected ExpressiveDbCommandBase(
		Func<TConnection> connFactory,
		CommandType type,
		string command,
		IEnumerable<Param>? @params = null)
		: base(connFactory, type, command, @params)
	{
	}

	/// <summary>
	/// Initializes a new instance that executes on an existing connection,
	/// optionally within a transaction.
	/// </summary>
	/// <include file="Commands.docs.xml" path="docs/members[@name='ctorConnectionTx']/*" />
	/// <include file="Commands.docs.xml" path="docs/members[@name='ctorCommon']/*" />
	protected ExpressiveDbCommandBase(
		TConnection connection,
		IDbTransaction? transaction,
		CommandType type,
		string command,
		IEnumerable<Param>? @params = null)
		: base(connection, transaction, type, command, @params)
	{
	}

	/// <summary>
	/// Initializes a new instance that executes on an existing connection.
	/// </summary>
	/// <include file="Commands.docs.xml" path="docs/members[@name='ctorConnection']/*" />
	/// <include file="Commands.docs.xml" path="docs/members[@name='ctorCommon']/*" />
	protected ExpressiveDbCommandBase(
		TConnection connection,
		CommandType type,
		string command,
		IEnumerable<Param>? @params = null)
		: base(connection, type, command, @params)
	{
	}

	/// <summary>
	/// Initializes a new instance that executes within a transaction, on the
	/// transaction's connection.
	/// </summary>
	/// <include file="Commands.docs.xml" path="docs/members[@name='ctorTx']/*" />
	/// <include file="Commands.docs.xml" path="docs/members[@name='ctorCommon']/*" />
	protected ExpressiveDbCommandBase(
		IDbTransaction transaction,
		CommandType type,
		string command,
		IEnumerable<Param>? @params = null)
		: base(transaction, type, command, @params)
	{
	}

	/// <summary>
	/// Reads the rows of an async terminal with <c>ReadAsync</c> instead of <c>Read</c>, for this command.
	/// </summary>
	/// <remarks>
	/// By default every terminal, async ones included, executes asynchronously and reads the rows with <c>Read</c>, the fastest and lightest way, also for large values.
	/// This opts in to <c>ReadAsync</c> (the getters stay synchronous, and the later result sets are read through with <c>NextResultAsync</c>) for this command only.
	/// A selector map (<c>Map(Func)</c>) on one very large value reads slower and uses more memory this way.
	/// It changes nothing on a synchronous terminal. The same call is available on the mapped views (<see cref="MappedQuery{T}.AsyncReads"/>), in any order with <c>Skip</c>, <c>Take</c> and <c>SingleResult</c>.
	/// </remarks>
	/// <returns>The same command.</returns>
	public TThis AsyncReads()
	{
		EnsureOptions().AsyncReads = true;
		return (TThis)this;
	}

	/// <summary>
	/// Gets whether <see cref="AsyncReads"/> was called.
	/// </summary>
	/// <remarks>
	/// The interface member is read by the views and by Channel (removed with
	/// the interface).
	/// </remarks>
	bool UsesAsyncReads => _options?.AsyncReads ?? false;

	/// <inheritdoc />
	bool IExecuteReaderAsync.UseAsyncRead => UsesAsyncReads;

	/// <summary>
	/// Asynchronously executes the command with
	/// <see cref="DbCommand.ExecuteNonQueryAsync(System.Threading.CancellationToken)"/>.
	/// </summary>
	/// <include file="Commands.docs.xml" path="docs/members[@name='token']/*" />
	/// <returns>
	/// A task that represents the asynchronous operation; its result is the
	/// number of rows affected, as the provider reports it.
	/// </returns>
	public ValueTask<int> ExecuteNonQueryAsync(
		CancellationToken cancellationToken = default)
		=> ExecuteCombinedAsync(
			cancellationToken,
			static (command, _, token)
				=> new ValueTask<int>(command.ExecuteNonQueryAsync(token)));

	/// <summary>
	/// Asynchronously executes the command with
	/// <see cref="DbCommand.ExecuteScalarAsync(System.Threading.CancellationToken)"/>.
	/// </summary>
	/// <inheritdoc cref="ExpressiveCommandBase{TConnection, TCommand, TReader, TDbType, TThis}.ExecuteScalar()"/>
	/// <include file="Commands.docs.xml" path="docs/members[@name='token']/*" />
	public ValueTask<object?> ExecuteScalarAsync(
		CancellationToken cancellationToken = default)
		=> ExecuteCombinedAsync(
			cancellationToken,
			static (command, _, token)
				=> new ValueTask<object?>(command.ExecuteScalarAsync(token)));

	/// <summary>
	/// Asynchronously executes the command with
	/// <see cref="DbCommand.ExecuteScalarAsync(System.Threading.CancellationToken)"/>
	/// and passes the value to a transform.
	/// </summary>
	/// <typeparam name="T">The type expected.</typeparam>
	/// <param name="transform">The function that converts the value. It receives <see langword="null"/> when the column is NULL or there is no row, never <see cref="DBNull"/>; any other value is passed as the provider returned it.</param>
	/// <include file="Commands.docs.xml" path="docs/members[@name='token']/*" />
	/// <returns>
	/// A task that represents the asynchronous operation; its result is the
	/// value returned from the transform.
	/// </returns>
	public async ValueTask<T> ExecuteScalarAsync<T>(
		Func<object?, T> transform,
		CancellationToken cancellationToken = default)
	{
		if (transform is null) throw new ArgumentNullException(nameof(transform));
		Contract.EndContractBlock();

		return transform(
			ScalarValue(
				await ExecuteScalarAsync(cancellationToken)
					.ConfigureAwait(false)));
	}

	/// <summary>
	/// Asynchronously executes the command with
	/// <see cref="DbCommand.ExecuteScalarAsync(System.Threading.CancellationToken)"/>
	/// and converts the value to the expected type, as <c>Map&lt;T&gt;()</c> converts a column.
	/// </summary>
	/// <inheritdoc cref="ExpressiveCommandBase{TConnection, TCommand, TReader, TDbType, TThis}.ExecuteScalar{T}()"/>
	/// <include file="Commands.docs.xml" path="docs/members[@name='token']/*" />
	public async ValueTask<T> ExecuteScalarAsync<T>(
		CancellationToken cancellationToken = default)
		// Converted after the command has released the connection.
		=> RowMap<T>.ConvertScalar(
			await ExecuteScalarAsync(cancellationToken)
				.ConfigureAwait(false));

	/// <summary>
	/// Asynchronously executes the command with
	/// <see cref="DbCommand.ExecuteScalarAsync(System.Threading.CancellationToken)"/>
	/// and passes the value to an asynchronous transform.
	/// </summary>
	/// <typeparam name="T">The type expected.</typeparam>
	/// <param name="transform">The function (task) that converts the value. It receives <see langword="null"/> when the column is NULL or there is no row, never <see cref="DBNull"/>; any other value is passed as the provider returned it.</param>
	/// <include file="Commands.docs.xml" path="docs/members[@name='token']/*" />
	/// <returns>
	/// A task that represents the asynchronous operation; its result is the
	/// value returned from the transform.
	/// </returns>
	public async ValueTask<T> ExecuteScalarAsync<T>(
		Func<object?, ValueTask<T>> transform,
		CancellationToken cancellationToken = default)
	{
		if (transform is null) throw new ArgumentNullException(nameof(transform));
		Contract.EndContractBlock();

		return await transform(
			ScalarValue(
				await ExecuteScalarAsync(cancellationToken)
					.ConfigureAwait(false)))
			.ConfigureAwait(false);
	}

	/// <summary>
	/// Reads the first column from every record and returns the results as a list.
	/// <see cref="DBNull"/> values are converted to <see langword="null"/>.
	/// </summary>
	/// <returns>
	/// A task that represents the asynchronous operation; its result is the
	/// list of values of the first column.
	/// </returns>
	public ValueTask<IEnumerable<object?>> FirstOrdinalResultsAsync()
		=> ExecuteReaderAsync(reader => reader.FirstOrdinalResultsAsync(UsesAsyncReads, CancellationToken), CommandBehavior.SequentialAccess | CommandBehavior.SingleResult);

	/// <summary>
	/// Reads the first column from every record.
	/// <see cref="DBNull"/> values are converted to <see langword="null"/>.
	/// </summary>
	/// <typeparam name="T0">The type to cast the values to.</typeparam>
	/// <returns>
	/// A task that represents the asynchronous operation; its result is the
	/// values of the first column, cast to <typeparamref name="T0"/>.
	/// </returns>
	public ValueTask<IEnumerable<T0>> FirstOrdinalResultsAsync<T0>()
		=> ExecuteReaderAsync(reader => reader.FirstOrdinalResultsAsync<T0>(UsesAsyncReads, CancellationToken), CommandBehavior.SequentialAccess | CommandBehavior.SingleResult);

	/// <summary>
	/// Asynchronously reads all records within the current result set and returns the desired results.
	/// </summary>
	/// <remarks>
	/// A <see langword="params"/> parameter must come last, so this overload takes no token:
	/// to cancel, use the overload that takes the <see cref="IEnumerable{T}"/> and a token.
	/// </remarks>
	/// <param name="n">The first ordinal to include in the request to the reader for each record.</param>
	/// <param name="others">The remaining ordinals to request from the reader for each record.</param>
	/// <returns>
	/// A task that represents the asynchronous operation; its result is the
	/// <see cref="QueryResultQueue{T}"/> that contains all the results and the column mappings.
	/// </returns>
	public ValueTask<QueryResultQueue<object[]>> RetrieveAsync(
		int n,
		params IEnumerable<int> others)
		=> RetrieveAsync(others.Prepend(n));

	/// <summary>
	/// Asynchronously reads all records within the current result set and returns the desired results.
	/// </summary>
	/// <remarks>
	/// A <see langword="params"/> parameter must come last, so this overload takes no token:
	/// to cancel, use the overload that takes the <see cref="IEnumerable{T}"/> and a token.
	/// </remarks>
	/// <param name="c">The first column name to include in the request to the reader for each record.</param>
	/// <param name="others">The remaining column names to request from the reader for each record.</param>
	/// <returns>
	/// A task that represents the asynchronous operation; its result is the
	/// <see cref="QueryResultQueue{T}"/> that contains all the results and the column mappings.
	/// </returns>
	public ValueTask<QueryResultQueue<object[]>> RetrieveAsync(
		string c,
		params IEnumerable<string> others)
		=> RetrieveAsync(others.Prepend(c));

	/// <summary>
	/// Asynchronously reads all records within the first result set and returns the results.
	/// </summary>
	/// <include file="Commands.docs.xml" path="docs/members[@name='token']/*" />
	/// <returns>
	/// A task that represents the asynchronous operation; its result is the
	/// <see cref="QueryResultQueue{T}"/> that contains all the results and the column mappings.
	/// </returns>
	public ValueTask<QueryResultQueue<object[]>> RetrieveAsync(
		CancellationToken cancellationToken = default)
		=> ExecuteReaderAsync(
			reader => reader.RetrieveAsync(
				UsesAsyncReads,
				cancellationToken),
			CommandBehavior.SingleResult,
			cancellationToken);

	/// <summary>
	/// Asynchronously reads all records within the current result set and returns the desired results.
	/// </summary>
	/// <param name="ordinals">The ordinals to request from the reader for each record.</param>
	/// <include file="Commands.docs.xml" path="docs/members[@name='token']/*" />
	/// <returns>
	/// A task that represents the asynchronous operation; its result is the
	/// <see cref="QueryResultQueue{T}"/> that contains all the results and the column mappings.
	/// </returns>
	public ValueTask<QueryResultQueue<object[]>> RetrieveAsync(
		IEnumerable<int> ordinals,
		CancellationToken cancellationToken = default)
		=> ExecuteReaderAsync(
			reader => reader.RetrieveAsync(
				ordinals,
				UsesAsyncReads,
				cancellationToken),
			CommandBehavior.SingleResult,
			cancellationToken);

	/// <summary>
	/// Asynchronously reads all records within the first result set and returns only the specified columns.
	/// </summary>
	/// <param name="columnNames">The column names to select.</param>
	/// <param name="normalizeColumnOrder"><see langword="true"/> to order the results arrays by ordinal; otherwise, <see langword="false"/>. The default is <see langword="false"/>.</param>
	/// <include file="Commands.docs.xml" path="docs/members[@name='token']/*" />
	/// <returns>
	/// A task that represents the asynchronous operation; its result is the
	/// <see cref="QueryResultQueue{T}"/> that contains all the results and the column mappings.
	/// </returns>
	public ValueTask<QueryResultQueue<object[]>> RetrieveAsync(
		IEnumerable<string> columnNames,
		bool normalizeColumnOrder = false,
		CancellationToken cancellationToken = default)
		=> ExecuteReaderAsync(
			reader => reader.RetrieveAsync(
				columnNames,
				normalizeColumnOrder,
				UsesAsyncReads,
				cancellationToken),
			CommandBehavior.Default,
			cancellationToken);
}
